://www.facebook.com/dw.stories","thumbnail":"https://i.ytimg.com/vi/zA6TWnquOYo/maxresdefault.jpg","category":"Documentaries","city":"","country":"","channel":"DW Documentary","channelTitle":"DW Documentary","channelId":"UCW39zufHfsuGgpLviKh297Q","badge":"DOCUMENTARY","publishedAt":"2017-05-21T02:00:02Z","viewCount":1676524,"durationSeconds":2546,"admission":{"version":3,"status":"channel-candidate","source":"channel-archive","mode":"DOCUMENTARIES"}}',1);
